-- Optional MySQL schema. SQLite is the default; see SHOP.md for configuration.
CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, description TEXT NOT NULL, category VARCHAR(30) NOT NULL, price INT NOT NULL, stock INT NOT NULL, image VARCHAR(255), sprite INT DEFAULT 0, color VARCHAR(20) DEFAULT '#e8a540', active TINYINT NOT NULL DEFAULT 1);
CREATE TABLE customers (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, invoice VARCHAR(32) NOT NULL UNIQUE, customer_id INT NULL, recipient VARCHAR(100) NOT NULL, whatsapp VARCHAR(25) NOT NULL, address TEXT NOT NULL, total INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Pending', created_at DATETIME NOT NULL, access_token VARCHAR(48) NOT NULL, FOREIGN KEY (customer_id) REFERENCES customers(id));
CREATE TABLE order_items (id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, product_id INT, product_name VARCHAR(100) NOT NULL, price INT NOT NULL, quantity INT NOT NULL, FOREIGN KEY (order_id) REFERENCES orders(id), FOREIGN KEY (product_id) REFERENCES products(id));
